followup_roundtrip.native_copies_command:
node <<'JS'
const fs=require('fs'),path=require('path'),crypto=require('crypto'),assert=require('assert/strict');
const dir='a7_recovery/unit_2154_g1_collection';
const id=JSON.parse(fs.readFileSync(dir+'/LAUNCH_IDENTITIES_2154.json'));
const proof=JSON.parse(fs.readFileSync(dir+'/PRESERVED_SEGMENT_2154.json'));
const saved=dir+'/evidence/'+id.accepted_run_id;
const hash=file=>crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
const pairs=[[saved+'/state.json',id.state_path],
             [saved+'/journal.jsonl',id.transcript_dir+'/journal.jsonl']];
for(const name of fs.readdirSync(saved))
  if(/^agent-.*\.(jsonl|meta\.json)$/.test(name))
    pairs.push([saved+'/'+name,id.transcript_dir+'/'+name]);
for(const [copy,original] of pairs){
  assert.equal(hash(copy),hash(original),copy);
  assert.equal(fs.statSync(copy).size,fs.statSync(original).size,copy);
}
assert.equal(pairs.length,62);
assert.equal(hash(saved+'/state.json'),proof.state_sha256);
assert.equal(hash(saved+'/journal.jsonl'),proof.journal_sha256);
console.log(JSON.stringify({byte_identical_native_copies:pairs.length,
  state_sha256:proof.state_sha256,journal_sha256:proof.journal_sha256,
  original_journal:id.transcript_dir+'/journal.jsonl',no_writes:true}));
