followup_roundtrip.base_input_comparison_command:
node <<'JS'
const fs = require('fs'), path = require('path'), crypto = require('crypto');
const assert = require('assert/strict');
const hash = bytes => crypto.createHash('sha256').update(bytes).digest('hex');
const canonical = value => JSON.stringify(value, (key, v) =>
  v && typeof v === 'object' && !Array.isArray(v)
    ? Object.fromEntries(Object.entries(v).sort()) : v);
function readQuestions(dir) {
  const bytes = fs.readFileSync(dir + '/a7_g1_candidate.json');
  const candidate = JSON.parse(bytes), questions = new Map();
  for (const row of candidate.batch_rows) {
    const prompt = fs.readFileSync(path.join(dir, row.prompt_path));
    assert.equal(hash(prompt), row.prompt_sha256);
    const text = prompt.toString(), boundary = text.indexOf('[EVENT]\n');
    assert(boundary >= 0);
    const body = JSON.parse(text.slice(boundary + 8));
    for (const event of body.events) for (const q of event.questions) {
      assert(!questions.has(q.question_id));
      questions.set(q.question_id, {
        question: canonical(q), context: canonical(event.event_context),
        rules: text.slice(0, boundary), whole_prompt: hash(prompt)
      });
    }
  }
  assert.equal(questions.size, candidate.questions);
  return { candidate_sha256: hash(bytes), questions };
}
const base = 'a7_recovery/unit_2020_codex_check';
const old = readQuestions(base + '/codex_g23partial2098_fit/G2');
const current = readQuestions(base + '/codex_currentg232157_b/G2');
let same = 0, changed = 0, novel = 0, whole = 0;
for (const [id, question] of current.questions) {
  const previous = old.questions.get(id);
  if (!previous) { novel++; continue; }
  if (previous.question === question.question &&
      previous.context === question.context &&
      previous.rules === question.rules) same++;
  else changed++;
  if (previous.whole_prompt === question.whole_prompt) whole++;
}
console.log(JSON.stringify({
  scope: 'DIAGNOSTIC ONLY: original-renderer inputs; failed current reporting job is NOT approval',
  original_candidate_sha256: old.candidate_sha256,
  current_candidate_sha256: current.candidate_sha256,
  original_questions: old.questions.size, current_questions: current.questions.size,
  same_question_context_original_rules: same, changed_same_id: changed, new_id: novel,
  removed_ids: [...old.questions.keys()].filter(id => !current.questions.has(id)).length,
  same_complete_prompt: whole, corrected_renderer_not_applied_here: true
}, null, 1));
